import itertools
from math import gcd

def is_good_set(U):
    if len(U) < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1
    for triple in itertools.combinations(U, 3):
        if gcd(triple[0], gcd(triple[1], triple[2])) != 1:
            return False

    # Condition 2: For any two distinct elements, there's a third that divides their product
    U_list = list(U)
    for i in range(len(U_list)):
        for j in range(i + 1, len(U_list)):
            u = U_list[i]
            v = U_list[j]
            found = False
            for k in range(len(U_list)):
                if k != i and k != j:
                    if (u * v) % U_list[k] == 0:
                        found = True
                        break
            if not found:
                return False
    return True

