    # m might be small. If m is small, the elements of U must be small.
    # Let's try elements from 1 to some limit.
    import itertools

    # This is too slow. Let's refine the search.
    # We can iterate over k (the size of U).
    for k in range(3, 7):
        # To keep m small, we need small u_i.
        # Let's try all combinations of u_i from {1, ..., 50}.
        # But that's too many. 50C3, 50C4...
        # Let's try combinations of u_i from {1, ..., 20}.
        # 20C3 = 1140, 20C4 = 4845, 20C5 = 15504. This is manageable.
        for U in itertools.combinations(range(1, 21), k):
